#!/usr/bin/env bash
# Print the signature that ends every comment issue-to-pr and pr-review post, right before their markers.
#   signature.sh [--agent claude-code|codex|chatgpt] [--model MODEL] [--effort LEVEL]
#
# Output (format: "Signature" in references/review-protocol.md):
#   ---
#   <sub>Generated by Claude Code · model `M` · effort `E` · session `S`</sub>
#   <!-- agent-signature v=1 agent=claude-code model=M effort=E session=S -->
#
# Pass what the agent knows about itself; the environment only fills what is not passed:
#   agent    --agent, else the environment when exactly one agent's hints are present
#            (CLAUDECODE=1 for Claude Code, CODEX_THREAD_ID for Codex), else unknown
#   model    --model, else ANTHROPIC_MODEL (claude-code only), else unknown
#   effort   --effort, else CLAUDE_EFFORT (claude-code only), else unknown
#   session  claude-code: CLAUDE_CODE_REMOTE_SESSION_ID (cloud), else CLAUDE_CODE_SESSION_ID (local)
#            codex: CODEX_THREAD_ID; otherwise unknown
# Environment variables are read only for the resolved agent, because one CLI launched from another can
# leave both agents' variables set. Never guess a value: anything not found is unknown.
set -euo pipefail

usage() {
  echo "usage: $0 [--agent claude-code|codex|chatgpt] [--model MODEL] [--effort LEVEL]" >&2
  exit 2
}

# A value goes into the hidden line as key=value and into the display line inside backticks, so it must
# have no whitespace, no backtick, no < or >, and no -- (which would break the HTML comment)
valid() {
  [ -n "$1" ] && [[ "$1" != *[[:space:]\`\<\>]* ]] && [[ "$1" != *--* ]]
}

agent="" model="" effort=""
while [ $# -gt 0 ]; do
  case "$1" in
    --agent | --model | --effort)
      [ $# -ge 2 ] || usage
      # An empty value counts as not passed
      if [ -n "$2" ] && ! valid "$2"; then
        echo "$0: invalid value for $1: '$2' (no spaces, backticks, <, > or --)" >&2
        exit 2
      fi
      case "$1" in
        --agent) agent="$2" ;;
        --model) model="$2" ;;
        --effort) effort="$2" ;;
      esac
      shift 2
      ;;
    *) usage ;;
  esac
done

case "$agent" in
  claude-code | codex | chatgpt | "") ;;
  *)
    echo "$0: unknown agent '$agent' (claude-code, codex or chatgpt)" >&2
    exit 2
    ;;
esac

if [ -z "$agent" ]; then
  hints=()
  [ "${CLAUDECODE:-}" = 1 ] && hints+=(claude-code)
  [ -n "${CODEX_THREAD_ID:-}" ] && hints+=(codex)
  if [ "${#hints[@]}" -eq 1 ]; then
    agent="${hints[0]}"
  else
    agent=unknown
  fi
fi

# from_env <value read for the resolved agent>: the value, or empty if it cannot go into the signature
from_env() {
  if [ -n "$1" ] && ! valid "$1"; then
    echo "$0: ignoring an environment value that cannot go into the signature: '$1'" >&2
    return
  fi
  printf '%s' "$1"
}

session=""
case "$agent" in
  claude-code)
    [ -n "$model" ] || model="$(from_env "${ANTHROPIC_MODEL:-}")"
    [ -n "$effort" ] || effort="$(from_env "${CLAUDE_EFFORT:-}")"
    # In a cloud session, CLAUDE_CODE_SESSION_ID is the container's own ID and cannot be traced from the web
    session="$(from_env "${CLAUDE_CODE_REMOTE_SESSION_ID:-}")"
    [ -n "$session" ] || session="$(from_env "${CLAUDE_CODE_SESSION_ID:-}")"
    ;;
  codex)
    session="$(from_env "${CODEX_THREAD_ID:-}")"
    ;;
esac

case "$agent" in
  claude-code) display="Claude Code" ;;
  codex) display="Codex" ;;
  chatgpt) display="ChatGPT" ;;
  *) display="an unknown agent" ;;
esac

model="${model:-unknown}" effort="${effort:-unknown}" session="${session:-unknown}"

printf -- '---\n'
# The backticks are Markdown code spans, not command substitution
# shellcheck disable=SC2016
printf '<sub>Generated by %s · model `%s` · effort `%s` · session `%s`</sub>\n' \
  "$display" "$model" "$effort" "$session"
printf '<!-- agent-signature v=1 agent=%s model=%s effort=%s session=%s -->\n' \
  "$agent" "$model" "$effort" "$session"
